import { useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { addMonths, isDisabled, monthGrid, monthLabel, sameDay, startOfMonth, weekdayLabels } from "../lib/calendar";
import type { CalendarDateMatcher } from "../lib/calendar";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface CalendarProps extends Omit<ViewProps, "children"> {
  value?: Date;
  onChange?: (date: Date) => void;
  month?: Date;
  onMonthChange?: (month: Date) => void;
  minDate?: Date;
  maxDate?: Date;
  disabledDates?: CalendarDateMatcher;
  locale?: string;
  weekStartsOn?: 0 | 1;
  showToday?: boolean;
  /** Draws a range between these two days (used by the date range picker). */
  range?: { start: Date; end?: Date | null };
  /** Extend the inner, named parts of the calendar: header, title, nav, weekday, day, dayText, selected or today. The React Native counterpart of `classNames`. */
  styles?: {
    header?: StyleProp<ViewStyle>;
    title?: StyleProp<TextStyle>;
    nav?: StyleProp<ViewStyle>;
    weekday?: StyleProp<TextStyle>;
    day?: StyleProp<ViewStyle>;
    dayText?: StyleProp<TextStyle>;
    selected?: StyleProp<ViewStyle>;
    today?: StyleProp<ViewStyle>;
  };
}

export function Calendar({ value, onChange, month, onMonthChange, minDate, maxDate, disabledDates, locale = "en-US", weekStartsOn = 0, showToday = true, range, style, styles: parts, ...props }: CalendarProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(startOfMonth(value ?? range?.start ?? new Date()));
  const shown = month ?? internal;
  const today = new Date();
  const days = monthGrid(shown, weekStartsOn);

  function go(count: number) {
    const next = addMonths(shown, count);
    if (month === undefined) setInternal(next);
    onMonthChange?.(next);
  }

  const inRange = (date: Date) => Boolean(range?.start && range.end && date >= range.start && date <= range.end);

  return (
    <View {...props} accessibilityRole="none" style={[{ alignSelf: "stretch" }, style]}>
      <View style={[local.header, parts?.header]}>
        <Pressable accessibilityRole="button" accessibilityLabel="Previous month" hitSlop={8} onPress={() => go(-1)} style={[local.nav, parts?.nav]}>
          <Text style={{ color: tokens.textSecondary, fontSize: 18 }}>‹</Text>
        </Pressable>
        <Text accessibilityRole="header" style={[{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "600" }, parts?.title]}>{monthLabel(shown, locale)}</Text>
        <Pressable accessibilityRole="button" accessibilityLabel="Next month" hitSlop={8} onPress={() => go(1)} style={[local.nav, parts?.nav]}>
          <Text style={{ color: tokens.textSecondary, fontSize: 18 }}>›</Text>
        </Pressable>
      </View>
      <View style={local.week}>
        {weekdayLabels(locale, weekStartsOn).map((label) => (
          <Text key={label} style={[local.cell, { color: tokens.textMuted, fontSize: metrics.text.xs }, parts?.weekday]}>{label.slice(0, 2)}</Text>
        ))}
      </View>
      <View style={local.grid}>
        {days.map((date) => {
          const outside = date.getMonth() !== shown.getMonth();
          const off = isDisabled(date, { minDate, maxDate, disabledDates });
          const selected = sameDay(date, value) || sameDay(date, range?.start) || sameDay(date, range?.end);
          const isToday = showToday && sameDay(date, today);
          return (
            <Pressable
              key={date.toISOString()}
              accessibilityRole="button"
              accessibilityLabel={date.toDateString()}
              accessibilityState={{ selected, disabled: off }}
              disabled={off}
              onPress={() => onChange?.(date)}
              style={[local.day, inRange(date) && !selected && { backgroundColor: tokens.surfaceMuted }, selected && { backgroundColor: tokens.controlOn }, isToday && !selected && { borderColor: tokens.borderStrong, borderWidth: 1 }, parts?.day, selected && parts?.selected, isToday && parts?.today]}
            >
              <Text style={[{ color: selected ? tokens.controlThumbOn : outside ? tokens.textMuted : tokens.foreground, opacity: off ? 0.4 : 1, fontSize: metrics.text.sm, fontVariant: ["tabular-nums"] }, parts?.dayText]}>{date.getDate()}</Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

const local = StyleSheet.create({
  header: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: metrics.space[2] },
  nav: { width: 32, height: 32, alignItems: "center", justifyContent: "center" },
  week: { flexDirection: "row" },
  grid: { flexDirection: "row", flexWrap: "wrap" },
  cell: { width: `${100 / 7}%`, textAlign: "center", paddingVertical: 6 },
  day: { width: `${100 / 7}%`, aspectRatio: 1, alignItems: "center", justifyContent: "center", borderRadius: 999 },
});

export default Calendar;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}

/**
 * Date helpers shared by the calendar, date picker and date range picker ports (React Native and Vue). Pure functions on
 * `Date`, no dependency: a month is always laid out as six weeks so the grid never changes height between months.
 */

export type CalendarDateMatcher = (date: Date) => boolean;

export interface CalendarLimits {
  minDate?: Date;
  maxDate?: Date;
  disabledDates?: CalendarDateMatcher;
}

export const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());
export const startOfMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth(), 1);
export const addMonths = (date: Date, count: number) => new Date(date.getFullYear(), date.getMonth() + count, 1);
export const addDays = (date: Date, count: number) => new Date(date.getFullYear(), date.getMonth(), date.getDate() + count);

export const sameDay = (a?: Date | null, b?: Date | null) =>
  Boolean(a && b) && a!.getFullYear() === b!.getFullYear() && a!.getMonth() === b!.getMonth() && a!.getDate() === b!.getDate();

/** The 42 days shown for a month, starting on `weekStartsOn` (0 is Sunday, 1 is Monday). */
export function monthGrid(month: Date, weekStartsOn: 0 | 1 = 0): Date[] {
  const first = startOfMonth(month);
  const offset = (first.getDay() - weekStartsOn + 7) % 7;
  return Array.from({ length: 42 }, (_, index) => addDays(first, index - offset));
}

/** Short weekday names in column order, in the given locale. */
export function weekdayLabels(locale = "en-US", weekStartsOn: 0 | 1 = 0): string[] {
  // 2024-01-07 was a Sunday.
  return Array.from({ length: 7 }, (_, index) => new Date(2024, 0, 7 + ((index + weekStartsOn) % 7)).toLocaleDateString(locale, { weekday: "short" }));
}

export const monthLabel = (month: Date, locale = "en-US") => month.toLocaleDateString(locale, { month: "long", year: "numeric" });

export function isDisabled(date: Date, { minDate, maxDate, disabledDates }: CalendarLimits): boolean {
  const day = startOfDay(date).getTime();
  return Boolean((minDate && day < startOfDay(minDate).getTime()) || (maxDate && day > startOfDay(maxDate).getTime()) || disabledDates?.(date));
}
